# ---- what they come to -----------------------------------------------------------
stat, spread, span, clear, errors = chain.stat, chain.spread, chain.span, chain.clear, chain.errors
TABLES = {"RUN": RUN, "GATE": GATE, "GIVEN": GIVEN}


def cells(table, w, kind, row, draw):
    """A run's cell for each of the five networks: from this file's tables, or for a row
    with eight bits from pta_board_chain.py's and pta_board_range.py's, which are the same
    runs."""
    core, way, images = row
    if BITS[way] == 8:
        return fitted.cells(table, w, kind, row, draw)
    return TABLES[table][w][kind][(core, way, images, draw)]


def shift(w, kind, row, n):
    """The shift of a network's last converter in a row: its step is two to that power.
    With nine bits and not fitted it is the one training's rule gave."""
    core, way, images = row
    if way == NINEFIT:
        return SHIFT[w][kind][images][n]
    return fitted.shift(w, kind, (core, TRAIN if way == NINE else way, images), n)


def noise_shift(w, kind, row, n):
    """The shift of the converter whose LSB a row's noise is in: the 8-bit one of its
    range."""
    core, way, images = row
    return shift(w, kind, (core, UNDER.get(way, way), images), n)


def top(row):
    """A row's converter's full scale, in its own steps."""
    return CODES[BITS[row[1]]]


def peak(w, kind, n, images):
    """The largest a network's declared reference is, which neither a range nor a width
    moves."""
    return chain.peak(w, kind, n, images)


def runs(w, kind, row, draw):
    return [c[0] for c in cells("RUN", w, kind, row, draw)]


def agrees(w, kind, row, draw):
    return [c[HOST] for c in cells("RUN", w, kind, row, draw)]


def declares(w, kind, row, draw):
    return [c[DECLARED_CLASS] for c in cells("RUN", w, kind, row, draw)]


def partner(row, draw):
    """The row and draw a row is read over: for a row with nine bits its own row with
    eight at the same range, of its draw.  A row with eight is read as pta_board_range.py
    reads it."""
    core, way, images = row
    if way in UNDER:
        return (core, UNDER[way], images), draw
    return fitted.partner(row, draw)


def diffs(w, kind, row, draw):
    return [p - x for p, x in zip(runs(w, kind, *partner(row, draw)), runs(w, kind, row, draw))]


def acc(w, kind, row, draw):
    return stat(runs(w, kind, row, draw))


def adds(w, kind, row, draw):
    return stat(diffs(w, kind, row, draw))


def by_net(w, kind, row, what=diffs):
    return [sum(what(w, kind, row, d)[i] for d in DRAWS) / len(DRAWS) for i in range(SEEDS)]


def by_draw(w, kind, row, what=diffs):
    return [sum(what(w, kind, row, d)) / SEEDS for d in DRAWS]


def over(w, kind, row):
    """What a row adds over the row it is read over, over the draws."""
    return stat(by_net(w, kind, row))


def draw_sd(w, kind, row):
    return spread(by_draw(w, kind, row))


def right(w, kind, row):
    return stat(by_net(w, kind, row, runs))


def right_sd(w, kind, row):
    return spread(by_draw(w, kind, row, runs))


def agree(w, kind, row, what=agrees):
    return stat(by_net(w, kind, row, what))


def agree_sd(w, kind, row, what=agrees):
    return spread(by_draw(w, kind, row, what))


def declared(w, kind, row):
    """How often the tile's class is its declared reference's in a row, over the draws."""
    return agree(w, kind, row, declares)


def gains(w, kind, row, under):
    """What a row gives its declared reference's class on, over what another row does:
    points, network by network, over the draws."""
    return stat([a - b for a, b in zip(by_net(w, kind, row, declares), by_net(w, kind, under, declares))])


def each_run(table, w, kind, row):
    """A table's cell for each of a row's 25 runs, network by network and then draw by draw."""
    return [cells(table, w, kind, row, d)[n] for n in range(SEEDS) for d in DRAWS]


def least(w, kind, row, which=HOST):
    return min(c[which] for c in each_run("RUN", w, kind, row))


def at_bar(w, kind, row, bar=GATE_CLASS, which=HOST):
    return sum(c[which] >= bar for c in each_run("RUN", w, kind, row))


def at_gate(w, kind, row):
    """The runs of 25 that pass the gate on the class: the declared reference's, on 99.5%."""
    return at_bar(w, kind, row, GATE_CLASS, DECLARED_CLASS)


def error(w, kind, row, table="GATE"):
    """A row's error over its runs, percent: its rms over the reference's rms, over the
    largest the reference is, and its largest over that, each a mean."""
    got = each_run(table, w, kind, row)
    return tuple(100 * sum(c[n] for c in got) / len(got) for n in range(3))


def most(w, kind, row, table="GATE"):
    return 100 * max(c[2] for c in each_run(table, w, kind, row))


def within(w, kind, row, table="GATE"):
    got = each_run(table, w, kind, row)
    return tuple(sum(100 * c[n] <= bar for c in got) for n, bar in ((0, GATE_RMS), (1, GATE_RMS), (2, GATE_MAX)))


def larger(w, kind, row):
    """For each network, by how many bits its step in a row is over the one training's
    rule gave: under nought where it is finer."""
    return [shift(w, kind, row, n) - chain.FULL[w][kind][n][0] for n in range(SEEDS)]


def past(w, kind, row):
    """The converter's range over a row's runs: the runs with a sum past it; the most sums
    past it in a run; the most the largest error is, percent of the largest the reference
    is, in the runs with none past it and in the runs with some; the runs whose step is
    not training's; and by how many bits it is larger at the most, and smaller."""
    pairs = list(zip(each_run("RUN", w, kind, row), each_run("GATE", w, kind, row)))
    some = [(r[2], 100 * g[2]) for r, g in pairs if r[2] > 0]
    none = [100 * g[2] for r, g in pairs if r[2] == 0]
    more = larger(w, kind, row)
    return (len(some), max((s for s, _ in some), default=0), max(none, default=0.0), max((z for _, z in some), default=0.0),
            len(DRAWS) * sum(b != 0 for b in more), max(more + [0]), max([-b for b in more] + [0]))


def sums(row):
    return OUTPUTS * row[2]


def in_steps(w, kind, row, n, draw, which=1):
    """A run's error in steps of its own converter: its rms (which=1) or its largest (2)."""
    return cells("GATE", w, kind, row, draw)[n][which] * peak(w, kind, n, row[2]) / 2 ** shift(w, kind, row, n)


def steps(w, kind, row, which=1):
    """A row's rms error against its declared format, in steps of the row's own converter:
    a mean over its 25 runs.  With which=2, its largest error."""
    xs = [in_steps(w, kind, row, n, d, which) for n in range(SEEDS) for d in DRAWS]
    return sum(xs) / len(xs)


def of_top(w, kind, row, which=1):
    """The same as a share of the converter's full scale, percent."""
    return 100 * steps(w, kind, row, which) / top(row)


def top_within(w, kind, row):
    """The runs whose rms is within the gate's 1.0% of the converter's full scale, and
    whose largest error is within its 2.0%."""
    return tuple(sum(100 * in_steps(w, kind, row, n, d, which) / top(row) <= bar for n in range(SEEDS) for d in DRAWS)
                 for which, bar in ((1, GATE_RMS), (2, GATE_MAX)))


def reach(w, kind, row):
    """For each network, the largest its declared reference is over the full scale of the
    converter the row gives it."""
    return [peak(w, kind, n, row[2]) / (top(row) * 2 ** shift(w, kind, row, n)) for n in range(SEEDS)]


def total(what, row, n=None):
    """A count over the three data sets and both kinds: 150 runs."""
    return sum(what(w, k, row) if n is None else what(w, k, row)[n] for w in WORKLOADS for k in KINDS)


def every(what, row, kinds=KINDS):
    return span([what(w, k, row) for w in WORKLOADS for k in kinds])


def moved(images):
    """The networks whose fitted 8-bit range is not the one training's rule gave, which are
    the ones whose reference reaches past it: (data set, kind, network)."""
    return [(w, k, n) for w, k, n, _ in fitted.moved(FIT, images)]


def cost(w, kind, n, images, way, under):
    """A network's rms error as budgeted one way over its rms error another, a mean over
    the draws.  Both are against one reference, so it is a ratio of errors in the sum's
    own units."""
    a, b = ("budget", way, images), ("budget", under, images)
    return sum(cells("GATE", w, kind, a, d)[n][0] / cells("GATE", w, kind, b, d)[n][0] for d in DRAWS) / len(DRAWS)


def costs(way, under, images=ALL, which=None):
    """That ratio for the networks fitting moved, or for the ones it left (which=False),
    or for all thirty (None)."""
    went = moved(images)
    return [cost(w, k, n, images, way, under) for w in WORKLOADS for k in KINDS for n in range(SEEDS)
            if which is None or ((w, k, n) in went) == which]


def as_was(row):
    """Of a row's 150 runs with nine bits, the ones that are their run with eight, figure
    for figure in every table; and the ones whose run with eight had no sum past its range."""
    core, way, images = row
    under = (core, UNDER[way], images)
    same = clean = 0
    for w in WORKLOADS:
        for k in KINDS:
            for d in DRAWS:
                for n in range(SEEDS):
                    same += all(cells(t, w, k, row, d)[n] == cells(t, w, k, under, d)[n] for t in TABLES)
                    clean += cells("RUN", w, k, under, d)[n][2] == 0
    return same, clean


# ---- what a ninth bit costs --------------------------------------------------------
def adc_w(bits):
    """One converter of that many effective bits at the plan's rate, watts: low and high."""
    return power.adc_w(bits, tighten.FS)


def adcs_w(bits):
    """The tile's converters, one a column."""
    return tuple(COLUMNS * x for x in adc_w(bits))


def chip_w(bits):
    """The interface chip at version 2 with converters of that many bits and nothing else
    changed: its other parts are pta_tighten.py's at eight."""
    parts = dict(tighten.chip_parts(BITS[TRAIN]), ADCs=adcs_w(bits))
    return sum(x[0] for x in parts.values()), sum(x[1] for x in parts.values())


def pm(x):
    return f"{x[0]:.2f} +-{x[1]:.2f}"


def dpm(x):
    return f"{x[0]:+.2f} +-{x[1]:.2f}"


def r2(x):
    return round(x[0], 2), round(x[1], 2)


def r3(x):
    return round(x[0], 3), round(x[1], 3)


def section(title):
    print(f"\n{title}\n{'-' * len(title)}")


def label(row):
    return NAME[row[0]] + ", " + WAY[row[1]] + (", a thousand" if row[2] == FEW else "")


def main():
    print("The first board's last layer, with a converter of one more bit.")
    print("pta_board_chain.py's networks and tile at version 2.  Five networks a kind, five draws.")
    heads = (f"  {'':<52}" + "".join(f"{w:>36}" for w in WORKLOADS) + "\n"
             + f"  {'':<52}" + "".join(f"{k:>18}" for w in WORKLOADS for k in KINDS))

    section("1. A row over its five draws: how often right, and what it adds over the row it is read over")
    for w in WORKLOADS:
        print(f"  {w:<54}{'before, right':>24}{'and adds':>24}{'reference, right':>24}{'and adds':>24}")
        for row in BASES:
            print(f"    {label(row):<52}" + "".join(f"{right(w, k, row)[0]:>10.3f} +-{right(w, k, row)[1]:.3f} {right_sd(w, k, row):>5.3f}"
                                               f"{over(w, k, row)[0]:>+10.3f} +-{over(w, k, row)[1]:.3f} {draw_sd(w, k, row):>5.3f}" for k in KINDS))

    section("2. The class the tile gives against the class its declared reference gives, percent; and the runs of 25 at 99.5% or more")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{declared(w, k, row)[0]:>9.3f} {at_gate(w, k, row):>2d} of 25" for w in WORKLOADS for k in KINDS))

    section("3. The last layer's rms error against its declared format, percent of the reference's rms")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{error(w, k, row)[0]:>18.3f}" for w in WORKLOADS for k in KINDS))
    section("4. The same in steps of the row's own converter, and as a share of its full scale, percent")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{steps(w, k, row):>10.3f}{of_top(w, k, row):>8.3f}" for w in WORKLOADS for k in KINDS))
    section("5. The largest error: a mean over the runs and the most of any, percent of the largest the reference is")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{error(w, k, row)[2]:>10.3f}{most(w, k, row):>8.3f}" for w in WORKLOADS for k in KINDS))
    section("6. Runs of 25 within the gate: 1.0% rms of the reference's rms, of its largest, of the converter's full scale; 2.0% largest of the reference's largest, of full scale")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{' '.join(str(n) for n in within(w, k, row)[:2] + top_within(w, k, row)[:1] + within(w, k, row)[2:] + top_within(w, k, row)[1:]):>18}"
                                                for w in WORKLOADS for k in KINDS))
    section("7. The converter's range: runs with a sum past it, the most in a run, runs whose step is not training's, and bits larger and smaller at the most")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<50}" + "".join(f"{past(w, k, row)[0]:>4d}{past(w, k, row)[1]:>5d}{past(w, k, row)[4]:>4d}{past(w, k, row)[5]:>2d}{past(w, k, row)[6]:>2d} " for w in WORKLOADS for k in KINDS))
    section("8. A network's rms error as budgeted, one way over another: the networks fitting moved, and the ones it left")
    for images in (ALL, FEW):
        print(f"    on {images:>6,} images, {len(moved(images))} moved of 30:")
        for way, under in ((NINE, TRAIN), (FIT, NINE), (NINEFIT, NINE), (NINEFIT, FIT)):
            went, left = costs(way, under, images, True), costs(way, under, images, False)
            print(f"      {WAY[way]:>18} over {WAY[under]:<18}  moved {min(went):.3f} to {max(went):.3f}, mean {sum(went) / len(went):.3f};"
                  f"  left {min(left):.3f} to {max(left):.3f}, mean {sum(left) / len(left):.3f}")
    section("9. What a ninth bit costs: this plan's converter at 1 GS/s, and the interface chip around it")
    for bits in (8, 9):
        print(f"    {bits} effective bits: {1e3 * adc_w(bits)[0]:.2f} to {1e3 * adc_w(bits)[1]:.2f} mW a converter; the tile's {COLUMNS}, {adcs_w(bits)[0]:.3f} to {adcs_w(bits)[1]:.3f} W;"
              f" the interface chip {chip_w(bits)[0]:.2f} to {chip_w(bits)[1]:.2f} W")

    said = io.StringIO()
    with contextlib.redirect_stdout(said):
        findings()
    print(said.getvalue(), end="")
    checks(" ".join(said.getvalue().split()))


def lohi(what, row, fmt="{:.2f}", kinds=KINDS):
    lo, hi = every(what, row, kinds)
    return f"{fmt.format(lo)} to {fmt.format(hi)}"


def three(what, kind=REFERENCE, fmt="{:.2f}"):
    return ", ".join(fmt.format(what(w, kind)) for w in WORKLOADS[:2]) + " and " + fmt.format(what(WORKLOADS[2], kind))


def with_past(rows):
    """The runs with a sum past the converter's range, over some rows, the three data sets
    and both kinds."""
    return sum(past(w, k, row)[0] for row in rows for w in WORKLOADS for k in KINDS)


def all_largest(rows):
    """Every run's largest error in some rows, percent of the largest the reference is."""
    return [100 * g[2] for row in rows for w in WORKLOADS for k in KINDS for g in each_run("GATE", w, k, row)]


def rows_of(way):
    """A way's four rows: the format alone and as budgeted, on 10,000 images and on a
    thousand."""
    return tuple((core, way, images) for images in (ALL, FEW) for core, _ in CORES)


def reaches(way):
    """How far every network's reference reaches into a way's range, on either count of
    images."""
    return [r for row in rows_of(way) if row[0] == "budget" for w in WORKLOADS for k in KINDS for r in reach(w, k, row)]


# What was written down before --gatebits had run any network (grx930's design note has the ten in
# full, timestamped 2026-10-13T15:29:15Z), for the reference networks on 10,000 images unless said:
# (number, what it said, how it came out).
def predictions():
    R = REFERENCE
    m, f, i = WORKLOADS
    TB, FF, FB, NB, GF, GB = (("budget", TRAIN, ALL), ("format", FIT, ALL), ("budget", FIT, ALL), ("budget", NINE, ALL),
                              ("format", NINEFIT, ALL), ("budget", NINEFIT, ALL))
    NBF = ("budget", NINE, FEW)
    e8, e9 = [error(w, R, TB)[0] for w in WORKLOADS], [error(w, R, NB)[0] for w in WORKLOADS]
    ef, eg = [error(w, R, FB)[0] for w in WORKLOADS], [error(w, R, GB)[0] for w in WORKLOADS]
    largest = [error(w, k, NB)[2] for w in WORKLOADS for k in KINDS]
    d = [declared(w, R, NB)[0] for w in WORKLOADS]
    g, gf = [declared(w, R, GB)[0] for w in WORKLOADS], [declared(w, R, GF)[0] for w in WORKLOADS]
    more = [gains(w, R, GB, FB)[0] for w in WORKLOADS]
    f9, f8 = [error(w, R, GF)[0] for w in WORKLOADS], [error(w, R, FF)[0] for w in WORKLOADS]
    finer = all(shift(w, k, row, n) == shift(w, k, (row[0], FIT, row[2]), n) - 1
                for w in WORKLOADS for k in KINDS for row in rows_of(NINEFIT) for n in range(SEEDS))
    return (
        (1, "with 9 bits at training's step no sum is past the range in any of its 600 runs",
         with_past(rows_of(NINE)) == 0),
        (2, "of those 600 runs, the 530 whose run with 8 bits had no sum past its range are that run, figure for figure",
         [sum(as_was(row)[n] for row in rows_of(NINE)) for n in (0, 1)] == [530, 530]),
        (3, "its rms as budgeted is within 0.03 of what it was with 8 and never over it: 4.46, 4.64 to 4.67 and 4.18% of the reference's rms",
         all(0 <= a - b <= 0.03 for a, b in zip(e8, e9)) and round(e9[0], 2) == 4.46 and 4.64 <= e9[1] <= 4.67 and round(e9[2], 2) == 4.18),
        (4, "its largest error as budgeted is 7.2 to 8.5% of the largest the reference is on every set and kind, 9.70% at the most, and within 2.0% in no run",
         all(7.2 <= x <= 8.5 for x in largest) and round(max(all_largest([NB])), 2) == 9.70 and total(within, NB, 2) == 0),
        (5, "the class is the declared reference's on 99.59 to 99.60, 96.78 to 96.82 and 99.23%; on the first thousand MNIST is 99.49% with 13 runs of 25 at 99.5%",
         99.585 <= d[0] <= 99.605 and 96.775 <= d[1] <= 96.825 and round(d[2], 2) == 99.23
         and round(declared(m, R, NBF)[0], 2) == 99.49 and at_gate(m, R, NBF) == 13),
        (6, "for the five networks fitting moved, the 8-bit fitted run has 1.20 to 1.27 times the rms error of the run with 9 bits at training's step",
         len(costs(FIT, NINE, ALL, True)) == 5 and all(1.20 <= c <= 1.27 for c in costs(FIT, NINE, ALL, True))),
        (7, "fitted with 9 bits every step is one bit finer than fitted with 8; the format alone has 0.36 to 0.64% of the reference's rms where it had 0.76 to 1.27, all 150 runs within 1.0% where 95 were, and a largest error of 0.39% at the most",
         finer and all(0.36 <= x <= 0.64 for x in f9) and [round(x, 2) for x in span(f8)] == [0.76, 1.27]
         and total(within, GF, 0) == 150 and total(within, FF, 0) == 95 and max(all_largest([GF])) <= 0.39),
        (8, "fitted with 9 bits and as budgeted the rms is 1 to 3% under what it is fitted with 8: 4.50 to 4.60, 4.90 to 5.00 and 4.06 to 4.15%",
         all(0.97 <= a / b <= 0.99 for a, b in zip(eg, ef)) and 4.50 <= eg[0] <= 4.60 and 4.90 <= eg[1] <= 5.00 and 4.06 <= eg[2] <= 4.15),
        (9, "and the class is the declared reference's 0.00 to 0.03 of a point more often than fitted with 8 on MNIST and on the inverted set and 0.03 to 0.12 more on Fashion-MNIST: 99.55 to 99.58, 96.23 to 96.32 and 99.23 to 99.26%",
         0 <= more[0] <= 0.03 and 0.03 <= more[1] <= 0.12 and 0 <= more[2] <= 0.03
         and 99.55 <= g[0] <= 99.58 and 96.23 <= g[1] <= 96.32 and 99.23 <= g[2] <= 99.26),
        (10, "the format alone, fitted with 9 bits, gives its declared reference's class on 99.88 to 99.93, 98.7 to 99.1 and 99.82 to 99.90% of 10,000 images",
         99.88 <= gf[0] <= 99.93 and 98.7 <= gf[1] <= 99.1 and 99.82 <= gf[2] <= 99.90),
    )


def findings():
    m, f, i = WORKLOADS
    R, B = REFERENCE, BEFORE
    TF, TB, FF, FB, NF, NB, GF, GB = (("format", TRAIN, ALL), ("budget", TRAIN, ALL), ("format", FIT, ALL), ("budget", FIT, ALL),
                                      ("format", NINE, ALL), ("budget", NINE, ALL), ("format", NINEFIT, ALL), ("budget", NINEFIT, ALL))
    TFF, TBF, FFF, FBF, NFF, NBF, GFF, GBF = (("format", TRAIN, FEW), ("budget", TRAIN, FEW), ("format", FIT, FEW), ("budget", FIT, FEW),
                                              ("format", NINE, FEW), ("budget", NINE, FEW), ("format", NINEFIT, FEW), ("budget", NINEFIT, FEW))
    rms_rms = lambda w, k, row: error(w, k, row)[0]
    max_peak = lambda w, k, row: error(w, k, row)[2]
    nine, eight = rows_of(NINE), rows_of(TRAIN)
    same, clean = (sum(as_was(row)[n] for row in nine) for n in (0, 1))
    kept, paid, still, fine = costs(NINE, TRAIN, ALL, True), costs(FIT, NINE, ALL, True), costs(NINEFIT, NINE, ALL, True), costs(NINEFIT, FIT)
    print()
    print("What this says, eight readings.  All of it is a stand-in classifier's, in a model.")
    print()
    print("  1. WITH NINE BITS AT THE SAME STEP, NO SUM IS PAST THE RANGE.  Not one, in any of its 600 runs, with the")
    print(f"     noise or without it, where {with_past(eight)} of the same 600 with eight bits had one.  Nothing is fitted: the step is the")
    print("     one training's rule gave, on training's images, and no golden manifest is read.  The largest any of")
    print(f"     the thirty networks' declared references is, is {max(reaches(NINE)):.2f} of the 9-bit converter's full scale, where it")
    print(f"     was {max(reaches(TRAIN)):.2f} of the 8-bit one's.")
    print()
    print("  2. AND THE ERROR IS THE ONE IT HAD.  A sum has the light it had and the noise it had.  Of the 600 runs,")
    print(f"     {same} are their run with eight bits, figure for figure: every one whose run with eight had no sum past")
    print(f"     its range.  The {len(kept)} networks that had some have {min(kept):.3f} to {max(kept):.3f} times the rms error they had.  So a")
    print(f"     set's rms as budgeted is {three(lambda w, k: rms_rms(w, k, NB))}% of the reference's rms for the reference networks,")
    print(f"     where it was {three(lambda w, k: rms_rms(w, k, TB))}%.  Fitted with eight bits, which is the other range that clips nothing,")
    print(f"     those {len(paid)} networks have {min(paid):.2f} to {max(paid):.2f} times the error they have with nine: the fifth more that")
    print("     fitting costs is not paid.")
    print()
    print("  3. THE LARGEST ERROR IS THEN THE NOISE'S, AS IT IS FITTED.  The format alone has a largest error of")
    print(f"     {min(all_largest([NF, NFF])):.2f} to {max(all_largest([NF, NFF])):.2f}% of the largest the reference is, where it was as much as {max(all_largest([TF, TFF])):.2f}%, and all 300 of its")
    print(f"     runs are within {GATE_MAX:.1f}%, where {total(within, TF, 2) + total(within, TFF, 2)} were.  As budgeted its mean over a set's runs is {lohi(max_peak, NB, '{:.1f}')}% on 10,000")
    print(f"     images, where it was {lohi(max_peak, TB, '{:.1f}')}%, and the most in any run {max(all_largest([NB])):.1f}%, where it was {max(all_largest([TB])):.1f}%.  No run of the")
    print(f"     300 as budgeted is within {GATE_MAX:.1f}%: the least is {min(all_largest([NB, NBF])):.1f}%.")
    print()
    print("  4. THE CLASS IS WHAT IT WAS.  As budgeted the reference networks give their declared reference's class")
    print(f"     on {three(lambda w, k: declared(w, k, NB)[0])}% of 10,000 images, where with eight bits and training's range they gave it")
    print(f"     on {three(lambda w, k: declared(w, k, TB)[0])}% and fitted on {three(lambda w, k: declared(w, k, FB)[0])}%.  On the first thousand it is")
    print(f"     {three(lambda w, k: declared(w, k, NBF)[0])}%, with {three(lambda w, k: at_gate(w, k, NBF), fmt='{:d}')} runs of 25 at {GATE_CLASS}%.  A clipped sum seldom moves a class, which")
    print("     is why training's rule lets one in ten thousand clip.  What fitting lost was to its larger step, and")
    print("     that is not taken here.")
    print()
    print("  5. SPENT ON FINER STEPS, THE BIT HALVES THE ROUNDING AND LEAVES THE NOISE.  Fitted with nine bits every")
    print("     network's step is one bit finer than fitted with eight, and the range is the same.  The format alone")
    print(f"     then has {lohi(rms_rms, GF)}% of the reference's rms, where it had {lohi(rms_rms, FF)}: all {total(within, GF, 0)} runs are within {GATE_RMS:.1f}%,")
    print(f"     where {total(within, FF, 0)} were.  As budgeted a network has {min(fine):.2f} to {max(fine):.2f} times its rms error fitted with eight, every one")
    print(f"     of the thirty: {three(lambda w, k: rms_rms(w, k, GB))}% for the reference networks, where it was {three(lambda w, k: rms_rms(w, k, FB))}%.  And the")
    print(f"     {len(still)} networks whose fitted range is twice training's still have {min(still):.2f} to {max(still):.2f} times the error they have")
    print("     with nine bits at training's step.  For those the two are one converter, the same step and the same")
    print("     range: what differs is the light.  Fitted, the top of the range has the light it had with eight, so")
    print("     a sum has half; at the same LSB a sum has what it had, and the receiver sees twice as much at the top.")
    print()
    print("  6. THE CLASS, WITH FINER STEPS.  Fitted with nine bits and as budgeted the reference networks give their")
    print(f"     declared reference's class on {three(lambda w, k: declared(w, k, GB)[0])}%: {three(lambda w, k: dpm(gains(w, k, GB, FB)), R, '{}')}")
    print(f"     points over fitted with eight, clear on Fashion-MNIST.  The format alone gives it on {three(lambda w, k: declared(w, k, GF)[0])}%,")
    print(f"     where fitted with eight it gave it on {three(lambda w, k: declared(w, k, FF)[0])}%.  On the first thousand as budgeted,")
    print(f"     {three(lambda w, k: at_gate(w, k, GBF), fmt='{:d}')} runs of 25 are at {GATE_CLASS}%.")
    print()
    print("  7. AS A SHARE OF FULL SCALE IT PASSES, WITH NOTHING BETTER ABOUT IT.  With nine bits at training's step")
    print(f"     the error is {lohi(steps, NB)} steps rms, as it was, and that is {lohi(of_top, NB)}% of a full scale twice as large.  All")
    print(f"     {total(top_within, NB, 0)} runs as budgeted are within {GATE_RMS:.1f}% of the converter's full scale, where {total(top_within, TB, 0)} were with eight bits.  None")
    print(f"     is within {GATE_RMS:.1f}% of the reference's rms, as none was.")
    print()
    print("  8. WHAT THE BIT COSTS.  This plan's converter of nine effective bits at 1 GS/s is")
    print(f"     {1e3 * adc_w(9)[0]:.2f} to {1e3 * adc_w(9)[1]:.2f} mW, where one of eight is {1e3 * adc_w(8)[0]:.2f} to {1e3 * adc_w(8)[1]:.2f}: the best published part is the same part, and the")
    print(f"     fifth-best takes twice the energy.  The tile's {COLUMNS} are {adcs_w(9)[0]:.2f} to {adcs_w(9)[1]:.2f} W, where they were {adcs_w(8)[0]:.2f} to {adcs_w(8)[1]:.2f}, and the")
    print(f"     interface chip {chip_w(9)[0]:.2f} to {chip_w(9)[1]:.2f} W, where B14 has {chip_w(8)[0]:.2f} to {chip_w(8)[1]:.2f}.  Not priced: a receiver that is linear to")
    print("     twice the photocurrent at the noise it had.  The plan has one figure for a receiver, whatever its range.")
    print()
    got = predictions()
    print(f"What it was predicted to say.  Ten, written before the option had run a network: {sum(ok for _, _, ok in got)} right.")
    for n, what, ok in got:
        print(f"  {n}. {'right' if ok else 'WRONG'}: {what}")


def checks(said):
    """Every claim above, as an assert.  `said` is the readings as printed, on one line."""
    m, f, i = WORKLOADS
    R, B = REFERENCE, BEFORE
    each = [(w, k) for w in WORKLOADS for k in KINDS]
    new = [row for row in BASES if BITS[row[1]] == 9]
    keys = [row + (d,) for d in DRAWS for row in BASES]
    held = [row + (d,) for d in DRAWS for row in new]
    assert len(keys) == 80 and len(held) == 40 and UNDER == {NINE: TRAIN, NINEFIT: FIT} and [BITS[w] for w, _ in WAYS] == [8, 8, 9, 9]
    assert set(RUN) == set(GATE) == set(GIVEN) == set(SHIFT) == set(WORKLOADS)
    assert set(PRINTED_ROWS) == set(PRINTED_OVER) == set(PRINTED_AGREE) == set(PRINTED_DECLARED) == set(PRINTED_GATE) == set(PRINTED_GIVEN) == set(PRINTED_RANGE) == set(WORKLOADS)
    for w, k in each:
        assert set(RUN[w][k]) == set(GATE[w][k]) == set(GIVEN[w][k]) == set(held), (w, k)
        assert set(SHIFT[w][k]) == {ALL, FEW} and all(len(SHIFT[w][k][x]) == SEEDS for x in SHIFT[w][k]), (w, k)
        for key in held:
            assert len(RUN[w][k][key]) == len(GATE[w][k][key]) == len(GIVEN[w][k][key]) == SEEDS
            for (a, g, s, d), (x, y, z), (e, u, v) in zip(RUN[w][k][key], GATE[w][k][key], GIVEN[w][k][key]):
                assert 0 <= a <= 100 and 50 < g <= 100 and 50 < d <= 100 and 0 <= s <= sums(key[:3]) / 100, (w, k, key)
                assert 0 < y <= z and 0 < x and 0 < u <= v and e > 0.02, (w, k, key)

    # 0. The figures are grx930's.  The seven tables its harness printed, every cell, from the
    #    networks' own figures: a row with eight bits from pta_board_chain.py's and pta_board_range.py's.
    def same(a, b, tol=0.0051):
        return abs(a[0] - b[0]) < tol and abs(a[1] - b[1]) < tol

    def same3(g, p, tol=0.00051):
        return len(g) == len(p) and all(abs(a - b) < tol for a, b in zip(g, p))

    count = 0
    for w in WORKLOADS:
        assert set(PRINTED_ROWS[w]) == set(keys)
        assert set(PRINTED_OVER[w]) == set(PRINTED_AGREE[w]) == set(PRINTED_DECLARED[w]) == set(PRINTED_GATE[w]) == set(PRINTED_GIVEN[w]) == set(PRINTED_RANGE[w]) == set(BASES)
        for key in keys:
            row, d = key[:3], key[3]
            got = (acc(w, B, row, d), adds(w, B, row, d), acc(w, R, row, d), adds(w, R, row, d))
            assert len(PRINTED_ROWS[w][key]) == 4 and all(same(a, b) for a, b in zip(got, PRINTED_ROWS[w][key])), (w, key)
            count += 4
        for row in BASES:
            got = [x for k in KINDS for x in (right(w, k, row) + (right_sd(w, k, row),), over(w, k, row) + (draw_sd(w, k, row),))]
            assert len(PRINTED_OVER[w][row]) == 4 and all(same3(g, p) for g, p in zip(got, PRINTED_OVER[w][row])), (w, row)
            count += 12
            for k, p in zip(KINDS, PRINTED_AGREE[w][row]):
                assert same3(agree(w, k, row) + (agree_sd(w, k, row),), p[:3]) and abs(least(w, k, row) - p[3]) < 1e-9, (w, k, row)
                assert (at_bar(w, k, row), 25) == p[4:], (w, k, row)
                count += 6
            for k, p in zip(KINDS, PRINTED_DECLARED[w][row]):
                assert same3(agree(w, k, row, declares) + (agree_sd(w, k, row, declares),), p[:3]), (w, k, row)
                assert abs(least(w, k, row, DECLARED_CLASS) - p[3]) < 1e-9 and (at_gate(w, k, row), 25) == p[4:6], (w, k, row)
                assert len(p) == 7 and abs(chain.declared_right(w, k, row[2]) - p[6]) < 0.00051, (w, k, row)
                count += 7
            for table, printed in (("GATE", PRINTED_GATE), ("GIVEN", PRINTED_GIVEN)):
                for k, p in zip(KINDS, printed[w][row]):
                    assert same3(error(w, k, row, table) + (most(w, k, row, table),), p[:4]) and within(w, k, row, table) == p[4:], (w, k, row, table)
                    count += 7
            for k, p in zip(KINDS, PRINTED_RANGE[w][row]):
                some, top_sums, none, where_some, steps_moved, bits, less = past(w, k, row)
                assert (some, 25, top_sums, sums(row)) == p[:4] and same3((none, where_some), p[4:6]) and (steps_moved, bits, less) == p[6:], (w, k, row)
                count += 9
    assert count == 3 * (80 * 4 + 16 * (12 + 12 + 14 + 14 + 14 + 18)) == 4992
    #    And a row with eight bits is the row the harness printed before: its tables' cells are
    #    pta_board_range.py's, figure for figure, which for training's range are pta_board_chain.py's.
    for w in WORKLOADS:
        for core, _ in CORES:
            for images in (ALL, FEW):
                for way in (TRAIN, FIT):
                    row = (core, way, images)
                    assert PRINTED_OVER[w][row] == fitted.PRINTED_OVER[w][row] and PRINTED_AGREE[w][row] == fitted.PRINTED_AGREE[w][row]
                    assert PRINTED_DECLARED[w][row] == fitted.PRINTED_DECLARED[w][row] and PRINTED_GATE[w][row] == fitted.PRINTED_GATE[w][row]
                    assert PRINTED_GIVEN[w][row] == fitted.PRINTED_GIVEN[w][row]
                    assert all(p[:8] == q and p[8] == 0 for p, q in zip(PRINTED_RANGE[w][row], fitted.PRINTED_RANGE[w][row]))
                    for d in DRAWS:
                        assert PRINTED_ROWS[w][row + (d,)] == fitted.PRINTED_ROWS[w][row + (d,)]
    TF, TB, FF, FB, NF, NB, GF, GB = (("format", TRAIN, ALL), ("budget", TRAIN, ALL), ("format", FIT, ALL), ("budget", FIT, ALL),
                                      ("format", NINE, ALL), ("budget", NINE, ALL), ("format", NINEFIT, ALL), ("budget", NINEFIT, ALL))
    TFF, TBF, FFF, FBF, NFF, NBF, GFF, GBF = (("format", TRAIN, FEW), ("budget", TRAIN, FEW), ("format", FIT, FEW), ("budget", FIT, FEW),
                                              ("format", NINE, FEW), ("budget", NINE, FEW), ("format", NINEFIT, FEW), ("budget", NINEFIT, FEW))
    eight, fit8, nine, fit9 = rows_of(TRAIN), rows_of(FIT), rows_of(NINE), rows_of(NINEFIT)
    assert nine == (NF, NB, NFF, NBF) and fit9 == (GF, GB, GFF, GBF) and eight == (TF, TB, TFF, TBF)

    def eq(got, want):
        assert got == want, (got, want)

    def six(what, digits=2):
        return [round(what(w, k), digits) for w, k in each]

    rms_rms = lambda row: (lambda w, k: error(w, k, row)[0])
    max_peak = lambda row: (lambda w, k: error(w, k, row)[2])
    went = moved(ALL)
    # What the two ways with nine bits are, held to each network.  At training's step the shift is the
    # one training's rule gave and the noise is in that LSB.  Fitted, the shift is the smallest at which
    # the largest the declared reference is, is within 255 codes; it is one under the 8-bit fitted one,
    # which is the shift its noise's LSB has; and the range is the 8-bit fitted one's and one step of
    # its own more.
    for w, k in each:
        for core, _ in CORES:
            for images in (ALL, FEW):
                for n in range(SEEDS):
                    a, g = (core, NINE, images), (core, NINEFIT, images)
                    s, p = shift(w, k, g, n), peak(w, k, n, images)
                    assert shift(w, k, a, n) == chain.FULL[w][k][n][0] == noise_shift(w, k, a, n), (w, k, a, n)
                    assert math.floor(p / 2 ** s + 0.5) <= CODES[9] < math.floor(p / 2 ** (s - 1) + 0.5), (w, k, g, n)
                    assert s == fitted.shift(w, k, (core, FIT, images), n) - 1 == noise_shift(w, k, g, n) - 1, (w, k, g, n)
                    assert (top(a), top(g), top((core, TRAIN, images)), top((core, FIT, images))) == (255, 255, 127, 127)
                    assert top(g) * 2 ** s - top((core, FIT, images)) * 2 ** (s + 1) == 2 ** s
    #    The format alone is one row whatever the draw, each way.
    assert all(cells(t, w, k, row, d) == cells(t, w, k, row, PLAN) for t in TABLES for w, k in each for row in (NF, NFF, GF, GFF) for d in DRAWS)
    eq([partner(row, 3) for row in (TF, TB, FB, NB, NFF, GB, GFF)], [(TF, PLAN), (TF, 3), (TB, 3), (TB, 3), (TFF, 3), (FB, 3), (FFF, 3)])

    # 1. Reading 1.  With nine bits at the same step no sum is past the range.
    eq((with_past(nine), with_past(fit9), with_past(eight), with_past(fit8)), (0, 0, 70, 0))
    assert sum(len(each_run("RUN", w, k, row)) for row in nine for w, k in each) == 600
    assert all(c[2] == 0 for row in nine + fit9 for w, k in each for c in each_run("RUN", w, k, row))
    assert all(b == 0 for w, k in each for row in nine for b in larger(w, k, row))
    eq([round(x, 3) for x in span(reaches(NINE))], [0.277, 0.661])
    eq([round(x, 3) for x in span(reaches(TRAIN))], [0.556, 1.327])
    #    A reference reaches half as far into twice the codes, less the one code more: 127 of 255.
    assert all(abs(a / b - 127 / 255) < 1e-12 for a, b in zip(reaches(NINE), reaches(TRAIN)))
    #    And the networks whose reference reaches past the 8-bit range are the five fitting moved.
    eq(went, [(m, R, 1), (f, R, 1), (f, R, 4), (i, B, 3), (i, B, 4)])
    eq(moved(FEW), [(f, R, 1), (i, B, 3)])
    for images in (ALL, FEW):
        eq(moved(images), [(w, k, n) for w, k in each for n in range(SEEDS) if chain.reach(w, k, images)[n] > 1])

    # 2. Reading 2.  And the error is the one it had.
    eq([as_was(row) for row in nine], [(125, 125), (125, 125), (140, 140), (140, 140)])
    eq((sum(as_was(row)[0] for row in nine), sum(as_was(row)[1] for row in nine)), (530, 530))
    #    A run that is not its run with eight is one whose run with eight had a sum past its range, and
    #    it has none.
    for row in nine:
        under = (row[0], TRAIN, row[2])
        for w, k in each:
            for d in DRAWS:
                for n in range(SEEDS):
                    was, now = cells("RUN", w, k, under, d)[n], cells("RUN", w, k, row, d)[n]
                    assert (was[2] > 0) == any(cells(t, w, k, row, d)[n] != cells(t, w, k, under, d)[n] for t in TABLES) and now[2] == 0
    kept, paid = costs(NINE, TRAIN, ALL, True), costs(FIT, NINE, ALL, True)
    eq([round(x, 4) for x in sorted(kept)], [0.9954, 0.9997, 0.9998, 1.0, 1.0001])
    eq([round(x, 3) for x in sorted(paid)], [1.202, 1.204, 1.208, 1.218, 1.236])
    assert all(c == 1.0 for c in costs(NINE, TRAIN, ALL, False)) and len(costs(NINE, TRAIN, ALL, False)) == 25
    eq([round(x, 3) for x in sorted(costs(NINE, TRAIN, FEW, True))], [1.0, 1.001])
    eq(six(rms_rms(NB), 3), [4.813, 4.464, 4.54, 4.669, 4.28, 4.183])
    eq(six(rms_rms(TB), 3), [4.813, 4.463, 4.54, 4.674, 4.28, 4.183])
    assert all(abs(a - b) < 0.006 for a, b in zip(six(rms_rms(NB), 3), six(rms_rms(TB), 3)))
    #    Not always under: on MNIST the reference networks' rms is a thousandth over what it was.  A
    #    converter that clips also clips a sum the noise had pushed past the range, which is no error.
    assert error(m, R, NB)[0] > error(m, R, TB)[0] and error(f, R, NB)[0] < error(f, R, TB)[0]

    # 3. Reading 3.  The largest error.
    eq([round(x, 2) for x in span(all_largest([NF, NFF]))], [0.3, 0.71])
    eq(round(max(all_largest([TF, TFF])), 2), 24.05)
    eq((total(within, NF, 2) + total(within, NFF, 2), total(within, TF, 2) + total(within, TFF, 2)), (300, 270))
    #    Half a step at the most for the format alone, each way with nine bits: to the three thousandths
    #    of a step that five printed digits leave of 255 codes.
    eq(round(max(in_steps(w, k, row, n, d, 2) for w, k in each for row in (NF, NFF, GF, GFF) for n in range(SEEDS) for d in DRAWS), 3), 0.501)
    assert all(in_steps(w, k, row, n, d, 2) <= 0.5 + 255e-5 for w, k in each for row in (NF, NFF, GF, GFF) for n in range(SEEDS) for d in DRAWS)
    eq(six(max_peak(NB), 3), [8.441, 7.566, 7.202, 7.19, 7.552, 7.44])
    eq(six(max_peak(TB), 3), [8.441, 8.024, 7.202, 11.528, 8.598, 7.44])
    eq(six(max_peak(FB), 3), [8.441, 7.947, 7.202, 7.915, 8.331, 7.44])
    eq([round(max(all_largest([row])), 2) for row in (NB, TB, FB, NBF)], [9.7, 24.05, 9.7, 9.98])
    eq(round(min(all_largest([NB, NBF])), 2), 5.95)
    eq(total(within, NB, 2) + total(within, NBF, 2), 0)

    # 4. Reading 4.  The class is what it was.
    eq(six(lambda w, k: declared(w, k, NB)[0], 3), [99.404, 99.587, 95.922, 96.779, 98.855, 99.233])
    eq(six(lambda w, k: declared(w, k, TB)[0], 3), [99.404, 99.587, 95.922, 96.779, 98.855, 99.233])
    eq(six(lambda w, k: declared(w, k, FB)[0], 3), [99.404, 99.546, 95.922, 96.2, 98.659, 99.233])
    eq(six(lambda w, k: declared(w, k, NBF)[0], 3), [99.248, 99.488, 96.012, 96.852, 98.796, 99.1])
    eq([at_gate(w, R, NBF) for w in WORKLOADS], [13, 0, 1])
    eq([at_gate(w, R, NBF) for w in WORKLOADS], [at_gate(w, R, TBF) for w in WORKLOADS])
    #    To a hundredth of a point on every set and kind: nine bits over eight at training's range.
    assert all(abs(gains(w, k, NB, TB)[0]) < 0.005 for w, k in each)
    eq([r3(gains(w, R, NB, FB)) for w in WORKLOADS], [(0.04, 0.04), (0.579, 0.362), (0.0, 0.0)])

    # 5. Reading 5.  Spent on finer steps.
    eq(six(rms_rms(GF), 3), [0.48, 0.419, 0.457, 0.637, 0.537, 0.38])
    eq(six(rms_rms(FF), 3), [0.959, 0.836, 0.913, 1.272, 1.073, 0.758])
    #    Half the rounding: the format alone has half the rms it has fitted with eight, to a hundredth.
    assert all(abs(error(w, k, GF)[0] / error(w, k, FF)[0] - 0.5) < 0.01 for w, k in each)
    eq((total(within, GF, 0), total(within, FF, 0), total(within, GFF, 0), total(within, NF, 0)), (150, 95, 150, 120))
    eq(round(max(all_largest([GF, GFF])), 2), 0.38)
    fine, still = costs(NINEFIT, FIT), costs(NINEFIT, NINE, ALL, True)
    eq((len(fine), round(min(fine), 3), round(max(fine), 3), round(sum(fine) / len(fine), 3)), (30, 0.968, 0.989, 0.98))
    eq([round(x, 3) for x in sorted(still)], [1.17, 1.171, 1.176, 1.183, 1.197])
    eq([round(x, 3) for x in span(costs(NINEFIT, NINE, ALL, False))], [0.973, 0.989])
    eq(six(rms_rms(GB), 3), [4.72, 4.566, 4.452, 4.91, 4.487, 4.117])
    eq(six(rms_rms(FB), 3), [4.813, 4.638, 4.54, 5.047, 4.606, 4.183])
    #    For the five the two ways are one converter: the same step, and so the same range.  And for the
    #    other twenty-five, fitted has a step a bit finer and half the range, which is the 8-bit one's.
    for w, k in each:
        for n in range(SEEDS):
            eq(shift(w, k, GB, n) == shift(w, k, NB, n), (w, k, n) in went)
            eq(shift(w, k, GB, n), shift(w, k, NB, n) - ((w, k, n) not in went))
            eq(noise_shift(w, k, GB, n) - noise_shift(w, k, NB, n), int((w, k, n) in went))
    #    The largest error is no smaller for it: the noise's.
    eq(six(max_peak(GB), 3), [8.332, 7.807, 7.114, 7.758, 8.131, 7.407])
    eq(total(within, GB, 2) + total(within, GBF, 2), 0)

    # 6. Reading 6.  The class, with finer steps.
    eq(six(lambda w, k: declared(w, k, GB)[0], 3), [99.446, 99.568, 96.36, 96.632, 98.761, 99.263])
    eq([r3(gains(w, R, GB, FB)) for w in WORKLOADS], [(0.022, 0.01), (0.431, 0.099), (0.03, 0.016)])
    eq([clear(gains(w, R, GB, FB)) for w in WORKLOADS], [False, True, False])
    eq(six(lambda w, k: declared(w, k, GF)[0], 3), [99.884, 99.906, 99.046, 99.054, 99.714, 99.87])
    eq(six(lambda w, k: declared(w, k, FF)[0], 3), [99.744, 99.81, 98.16, 97.97, 99.36, 99.728])
    eq([at_gate(w, R, GBF) for w in WORKLOADS], [15, 0, 3])
    #    On Fashion-MNIST it is still under what nine bits at training's step give.
    eq([r3(gains(w, R, NB, GB)) for w in WORKLOADS], [(0.018, 0.031), (0.148, 0.332), (-0.03, 0.016)])
    assert not any(clear(gains(w, R, NB, GB)) for w in WORKLOADS)

    # 7. Reading 7.  As a share of full scale.
    eq([round(x, 2) for x in every(steps, NB)], [1.43, 1.83])
    eq([round(x, 2) for x in every(steps, TB)], [1.43, 1.83])
    eq([round(x, 2) for x in every(of_top, NB)], [0.56, 0.72])
    eq([round(x, 2) for x in every(of_top, TB)], [1.13, 1.44])
    eq([total(top_within, row, 0) for row in (TB, FB, NB, GB)], [20, 45, 150, 49])
    eq([total(within, row, 0) for row in (TB, FB, NB, GB)], [0, 0, 0, 0])
    eq([total(top_within, row, 1) for row in (TB, FB, NB, GB)], [0, 0, 0, 0])

    # 8. Reading 8.  What the bit costs: this plan's own converter, and its interface chip around it.
    eq(adcs_w(8), tighten.chip_parts(8)["ADCs"])
    eq(adcs_w(9), tighten.chip_parts(9)["ADCs"])
    eq(chip_w(8), tighten.chip_w(8))
    eq([round(1e3 * x, 3) for x in adc_w(8) + adc_w(9)], [4.194, 5.346, 4.194, 10.812])
    eq([round(x, 3) for x in adcs_w(8) + adcs_w(9)], [0.268, 0.342, 0.268, 0.692])
    eq([round(x, 2) for x in chip_w(8) + chip_w(9)], [0.64, 4.18, 0.64, 4.53])
    assert adc_w(9)[0] == adc_w(8)[0] and 2.0 < adc_w(9)[1] / adc_w(8)[1] < 2.05
    assert chip_w(9)[0] == chip_w(8)[0] and abs(chip_w(9)[1] - chip_w(8)[1] - 0.35) < 0.001
    #    The plan's receivers are one figure whatever the converter.
    eq(tighten.chip_parts(8)["receivers"], tighten.chip_parts(9)["receivers"])

    # 9. The predictions: seven of ten.
    got = predictions()
    eq([n for n, _, ok in got if not ok], [3, 4, 9])
    assert len(got) == 10

    # 10. And the readings say those figures, each in its place.
    for words in (
        "Not one, in any of its 600 runs, with the noise or without it, where 70 of the same 600 with eight bits had one.",
        "is 0.66 of the 9-bit converter's full scale, where it was 1.33 of the 8-bit one's.",
        "530 are their run with eight bits, figure for figure",
        "The 5 networks that had some have 0.995 to 1.000 times the rms error they had.",
        "is 4.46, 4.67 and 4.18% of the reference's rms for the reference networks, where it was 4.46, 4.67 and 4.18%.",
        "those 5 networks have 1.20 to 1.24 times the error they have with nine",
        "a largest error of 0.30 to 0.71% of the largest the reference is, where it was as much as 24.05%, and all 300 of its runs are within 2.0%, where 270 were.",
        "is 7.2 to 8.4% on 10,000 images, where it was 7.2 to 11.5%, and the most in any run 9.7%, where it was 24.1%.",
        "No run of the 300 as budgeted is within 2.0%: the least is 6.0%.",
        "on 99.59, 96.78 and 99.23% of 10,000 images, where with eight bits and training's range they gave it on 99.59, 96.78 and 99.23% and fitted on 99.55, 96.20 and 99.23%.",
        "On the first thousand it is 99.49, 96.85 and 99.10%, with 13, 0 and 1 runs of 25 at 99.5%.",
        "then has 0.38 to 0.64% of the reference's rms, where it had 0.76 to 1.27: all 150 runs are within 1.0%, where 95 were.",
        "As budgeted a network has 0.97 to 0.99 times its rms error fitted with eight, every one of the thirty: 4.57, 4.91 and 4.12% for the reference networks, where it was 4.64, 5.05 and 4.18%.",
        "5 networks whose fitted range is twice training's still have 1.17 to 1.20 times the error they have with nine bits at training's step.",
        "declared reference's class on 99.57, 96.63 and 99.26%: +0.02 +-0.01, +0.43 +-0.10 and +0.03 +-0.02 points over fitted with eight, clear on Fashion-MNIST.",
        "The format alone gives it on 99.91, 99.05 and 99.87%, where fitted with eight it gave it on 99.81, 97.97 and 99.73%.",
        "15, 0 and 3 runs of 25 are at 99.5%.",
        "the error is 1.43 to 1.83 steps rms, as it was, and that is 0.56 to 0.72% of a full scale twice as large.",
        "All 150 runs as budgeted are within 1.0% of the converter's full scale, where 20 were with eight bits. None is within 1.0% of the reference's rms, as none was.",
        "is 4.19 to 10.81 mW, where one of eight is 4.19 to 5.35",
        "The tile's 64 are 0.27 to 0.69 W, where they were 0.27 to 0.34, and the interface chip 0.64 to 4.53 W, where B14 has 0.64 to 4.18.",
        "Ten, written before the option had run a network: 7 right.",
    ):
        assert said.count(words) == 1, words
    assert said.count(" right: ") == 7 and said.count(" WRONG: ") == 3

    print()
    print("All checks pass.")


if __name__ == "__main__":
    main()
